css:
.button {
  background-color: #fff;
  height: 40px;
  width: 120px;
  border-radius: 10px;
  border: 1px solid #add8e6;
  box-shadow: 3px 3px #fff, 5px 5px #add8e6;
  color: #add8e6;
  font-weight: 700;
  transition: box-shadow 300ms linear;
}

.button:hover {
  box-shadow: none;
  color: #fff;
  background-color: #add8e6;
  cursor: pointer;
}
